T1558.003.kql:
let lookback = 1h;
SecurityEvent
| where TimeGenerated > ago(lookback)
| where EventID == 4769
| where TicketEncryptionType in ("0x17", "0x18")   // RC4 / weak - modern clients use AES
| where ServiceName !endswith "$"                   // exclude machine accounts
| where ServiceName != "krbtgt"
| where TargetUserName !endswith "$"
| extend ClientIP = tostring(split(IpAddress, ":")[0])
| summarize
    DistinctServices = dcount(ServiceName),
    Services         = make_set(ServiceName, 40),
    RequestCount     = count(),
    SourceIPs        = make_set(ClientIP, 10),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
    by TargetUserName, Computer
| where DistinctServices >= 8
| order by DistinctServices desc
// TUNING: requires 4769 collection from DCs. If you do not have that, use
//         Defender for Identity's built-in Kerberoasting alert via the
//         SecurityAlert table instead.
